// Des: Tests that every job name maps to its job
// Flo: dispatch by name on the sim > read page state
// I/O: job words > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const jobs = @import("ru-jobs-main.zig"); const rig = @import("te-rigz-main.zig"); const T = std.testing;
test "job table: known names, ask jobs, unknown names" { try T.expect(jobs.known("send")); try T.expect(jobs.known("react")); try T.expect(jobs.known("cloud")); try T.expect(!jobs.known("dance")); try T.expect(jobs.isAsk("recall")); try T.expect(jobs.isAsk("friend")); try T.expect(!jobs.isAsk("send")); try T.expect(!jobs.isAsk("nonsense")); var asks: u32 = 0; for (jobs.SPECS) |sp| { if (sp.ask) asks += 1; } try T.expect(asks >= 10); }
test "arity is checked for every job before any page action" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); for (jobs.SPECS) |sp| { if (sp.need == 0) continue; try T.expectError(error.BadJob, jobs.dispatch(&ses, sp.name, &.{})); } try T.expectError(error.BadJob, jobs.dispatch(&ses, "dance", &.{"x"})); try T.expectEqual(@as(i64, 0), try rg.num("Z.st.sent.length")); }
test "jobs by name reach the right page action" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); _ = try jobs.dispatch(&ses, "react", &.{ "Mom", "Dinner", "👍" }); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.reacts.length")); _ = try jobs.dispatch(&ses, "poll", &.{ "Team A", "Where?", "Pho", "Bun" }); try T.expectEqualStrings("Where?|Pho|Bun", try rg.js("Z.st.polls[0]")); _ = try jobs.dispatch(&ses, "note", &.{ "Mom", "two", "words" }); try T.expectEqualStrings("two words", try rg.js("Z.st.notes[0]")); _ = try jobs.dispatch(&ses, "quick", &.{ "hi", "Hello", "there" }); try T.expectEqualStrings("hi|Hello there", try rg.js("Z.st.quick[0]")); _ = try jobs.dispatch(&ses, "accept", &.{"Lan"}); try T.expectEqualStrings("Lan", try rg.js("Z.st.accepted[0]")); _ = try jobs.dispatch(&ses, "rename", &.{ "Team A", "Team", "Z" }); try T.expectEqualStrings("Team A->Team Z", try rg.js("Z.st.renamed[0]")); _ = try jobs.dispatch(&ses, "archive", &.{"Boss"}); try T.expectEqualStrings("Boss", try rg.js("Z.st.arch[0]")); _ = try jobs.dispatch(&ses, "sticker", &.{ "Mom", "Yêu" }); try T.expectEqualStrings("Yêu", try rg.js("Z.st.stickers[0]")); }
test "ask jobs need force; cloud writes to the My Cloud chat in either language" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var live = rg.ses(rig.cfgOf(), .live); try T.expectError(error.NeedForce, jobs.dispatch(&live, "friend", &.{"0900000009"})); try T.expectError(error.NeedForce, jobs.dispatch(&live, "leave", &.{"Team A"})); const rep = try jobs.dispatch(&live, "cloud", &.{ "note", "to", "self" }); try T.expectEqual(@as(u32, 1), rep.sent); try T.expectEqualStrings("Cloud của tôi|note to self", try rg.js("Z.st.sent[0]")); _ = try rg.js("Z.set('lang','en');'x'"); live.fake_ms += 600000; _ = try jobs.dispatch(&live, "cloud", &.{"again"}); try T.expectEqual(@as(i64, 2), try rg.num("Z.st.sent.length")); var frc = rg.ses(rig.cfgOf(), .force); frc.fake_ms += 1200000; _ = try jobs.dispatch(&frc, "friend", &.{"0900000009"}); try T.expectEqualStrings("0900000009", try rg.js("Z.st.req[0]")); }
